use super::*;

/// What `--measure-only` says on stderr, or `None` when there is nothing honest to say.
///
/// # Why this line exists at all
///
/// MEASURED 2026-09-03: `bsc errors run --measure-only` is a pure tee, so its output is BYTE-IDENTICAL
/// to the unwrapped command. A caller whose whole job is to report what a surface COSTS therefore got
/// back no cost and no sign that anything had been recorded, and looped for twelve minutes escalating
/// through `2>&1`, `; echo EXIT_CODE=$?`, `| tee /tmp/…` and finally `time bsc errors run …` — timing
/// the wrapper by hand to recover the number the wrapper already had. All ten of its runs recorded
/// perfectly; the data was one command away the entire time and nothing pointed at it.
///
/// The fix is not a repetition guard. It is telling the caller what happened and what to do next,
/// which helps every reader including the ones that never loop.
///
/// # It is stderr, and that is load-bearing
///
/// The whole value of the tee is that stdout is the child's, untouched — `npm run gate` pipes these,
/// and a line of ours in the middle would corrupt every one. So this returns a String for the caller
/// to write to stderr, exactly as the fault note on the tee path already does.
///
/// # An interrupt has nothing to acknowledge
///
/// [`record_run`] refuses an interrupted run, because Ctrl-C part-way through a build gives a wall
/// clock that measures how long someone waited. Returning `None` here keeps this line from announcing
/// a cost that no row holds — the gate is IN this function rather than at the call site so every rule
/// the ack obeys is reachable by a unit test.
pub fn measure_ack(
    source: &str,
    cost: &Cost,
    outcome: &Outcome,
    recorded: bool,
    db: Option<&std::path::Path>,
) -> Option<String> {
    if outcome.interrupted {
        return None;
    }
    let peak = match cost.peak_rss_bytes {
        Some(b) => format!("peak {:.0} MB", b as f64 / 1_048_576.0),
        // NOT "0 MB", and not silence. A sub-second command never lives long enough to give the 200 ms
        // sampler a single walk, so absent is the NORMAL outcome for a fast one — measured: 10 of 10
        // runs of `bsc studio list`. A caller shown only a wall clock cannot tell that from a memory
        // figure that failed to write, and goes looking for a half that was never going to be there.
        None => "peak not sampled (the run ended inside one 200 ms sampling interval)".to_string(),
    };
    let head = format!("[measured] {source} · {} · {peak}", ack_ms(cost.ms));
    Some(match (recorded, db) {
        (true, Some(path)) => {
            format!("{head}\n[measured] recorded — read the trend with: {}", mem_read_back(path, source))
        }
        // Silence here is the exact failure this line exists to remove: "no store" is the one answer a
        // caller cannot infer from output that is byte-identical to the unwrapped command. Saying it
        // does not make the wrapper a gate — the exit code, stdout and the timing are all untouched.
        (_, None) => format!(
            "{head}\n[measured] NOT recorded: no error store — name one with --project <key> or --db <path>"
        ),
        (false, Some(path)) => format!(
            "{head}\n[measured] NOT recorded: could not write {} — the command itself ran and its exit code is unchanged",
            path.display()
        ),
    })
}
